      research:['{target}。……興味はある。光を抑える技術なら、なおいい。', '任せる。私は、研究所の夜番をしておく。'],
      recruit: ['{target}を連れてくる。……穏便に、だな。', '影に生きる者の扱いなら、少しは分かる。'],
      staff:   ['参謀。……では、敵の弱みから話す。', '私の策は、表には出せないものが多い。それでいいなら。'],
      month:   ['今月も、何事もなく。……それが一番いい。', '昨夜は、少し眠れた。', '窓辺の月が細い。動くなら、今月だ。'],
      win:     ['終わった。……誰も、気づかないうちに。', '標的、沈黙。'],
      lose:    ['……読まれていた。次は、読ませない。', '退く。影は、生き延びてこそ影だ。'],
      bstart:  ['灯火を消せ。始める。', '……来る。静かに。'],
