      research:['{target}？ 取材させて。民に分かる言葉で書くわ。', '技術の話は難しいけど、それで何が変わるかなら書ける。'],
      recruit: ['{target}ね。噂は色々聞いてる。本人の話を聞きに行くわ。', '人を口説くのは取材と同じ。相手が話したいことを、先に聞くの。'],
      staff:   ['参謀？ 私が？ ……耳に痛いことも言うわよ。', 'いいわ。私の手帳には、この国の弱点が山ほど書いてある。'],
      month:   ['今月の見出しは、明るいものだといいわね。', 'コーヒーが切れた。……締め切りより、こっちの方が深刻だわ。', '昨日、前線の兵士から手紙が来たの。読む？'],
