      bskill:  ['今よ！ 敵の動き、全部手帳に書いてある！', '特ダネは、待っていても来ないのよ！'],
      promote: ['記者が昇進？ ……自分の記事にはしづらいわね。', 'ありがとう。でも、筆は曲げないわよ。'],
      join:    ['サラ・ベネット、戦場記者よ。{faction}の戦を、内側から書かせてもらうわ。', '{honor}。私は宣伝係にはならない。それでよければ。'],
      refuse:  ['ごめんなさい。記者が旗を背負ったら、もう記者じゃないの。', '私の筆は、誰の物でもないわ。'],
