      appoint: ['総督？ 手配書の顔が、星の顔になるのか。笑えるな。', '{target}を預かる。まずは、悪党の逃げ道を全部塞ぐ。'],
      govern:  ['{target}の坑道を見てくる。ああいう所は、たいてい誰かが泣いてる。', '働く奴らに、ちゃんと払ってるか？ それが最初だ。'],
      envoy:   ['俺を使者に？ 向こうで捕まっても知らねえぞ。', '{target}か。手配書が出回ってなけりゃいいがな。'],
      research:['{target}？ 新しい玩具か。早く撃たせてくれよ。', '学者先生がた、頑張ってくれ。俺は試し撃ちを担当する。'],
      recruit: ['{target}を口説くのか。脛に傷のある奴なら、話は早い。', '追われてる奴には、帰る場所を見せてやればいい。'],
      staff:   ['参謀か。俺の策は汚えぞ。それでよけりゃ。', '賞金首の知恵を借りるとはな。いいぜ、高くつくが。'],
      month:   ['今月も手配書の額が上がった。人気者はつらいね。', '酒がうまい月は、何か起きる。', '借りってのは、返すまで忘れられねえもんだ。'],
      win:     ['はっ、ざまあみろ。俺の首は安くねえんだよ。', '勝った勝った。祝杯だ、高いやつでな。'],
