      order:   { a: 'ふん、弟子に指図されるとはな。……よかろう。', b: '承知しました、先生。' },
      capture: { a: 'ユーリが捕らわれただと……。老いぼれの命と替えてでも取り返す。', b: '先生が捕らわれた……。今度こそ、置いていかない。' },
      death:   { a: 'ユーリ……。弟子が先に逝くとは、親不孝もんが……', b: '先生……。また、私だけが生き残ってしまった……' },
      recruit: { a: 'ユーリ、来い。儂の最後の弟子として、もう一度鍛え直してやる。', b: '先生、こちらへ。もう一度、先生の下で戦わせてください。' },
