      ally:    { a: 'イヴ、壊れても大丈夫だからね！ わたしがいるから！', b: '姉さん、損傷艦の位置を送ります。修理をお願いします。' },
      staff:   { a: 'イヴ、敵の動き、演算してくれる？', b: '姉さん、修理班の指揮をお願いします。' },
