      death:   { a: 'イヴ……。直せないもの、ないって……言ったのに……', b: '姉さん……。私の膝が、またきしみます……' },
      recruit: { a: 'イヴ、こっちにおいで。毎晩、手入れしてあげるから！', b: '姉さん、来てください。あなたの工具箱の場所は、空けてあります。' },
      memory:  { a: 'イヴの膝の油、今でもつい用意しちゃうんです。', b: '姉さんの手の温度を、記録から消せません。' },
