      enemy:   { a: 'ゼロが向こうに……。あの人と戦う日が来るなんて。', b: 'ノアが敵の国に。……あの声に、砲は向けられない。' },
      battle:  { a: 'ゼロ、どうか退いて。あなたを嵐から守ったのは、こんな日のためじゃない。', b: 'ノア、下がっていろ。お前の船には当てない。' },
      ally:    { a: 'ゼロ、記録は私が取ります。思う存分。', b: 'ノア、俺の後ろにいろ。今度は俺が守る。' },
      staff:   { a: 'ゼロ、古い記録の通りなら、敵はそこで崩れます。', b: 'ノア、後方で記録を頼む。お前の目が要る。' },
      order:   { a: '分かりました、ゼロ。', b: '了解した、ノア。' },
      capture: { a: 'ゼロが捕らわれた……。今度は、私が迎えに行きます。', b: 'ノアが捕らわれた。……俺が行く。誰も止めるな。' },
      death:   { a: 'ゼロ……。また、返事のない人に話しかける日々に戻るのですね。', b: 'ノア……。今度は、俺が話しかける番だったのに。' },
      recruit: { a: 'ゼロ、こちらへ。あなたの話を、聞かせてください。', b: 'ノア、来い。嵐の星より、ここの方が暖かい。' },
      memory:  { a: '嵐の音を聞くと、あの棺のそばの夜を思い出します。', b: '静かな夜には、あの男の声が聞こえる気がする。' },
