      death:   { a: '審問官……。最後に、記録の頁を開いてくださったのですね。', b: 'ラングレー……。お前の書いたものは、燃やさずに残しておく。' },
      recruit: { a: '審問官、こちらへ。共に古文書を読みましょう。', b: 'ラングレー、来い。お前の記録を、私の目の前で証明してみせろ。' },
